import { sql } from "drizzle-orm";
import {
  check,
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
  type AnySQLiteColumn,
} from "drizzle-orm/sqlite-core";
import {
  ACCOUNT_STATUSES,
  ADMIN_ROLES,
  AVAILABILITY,
  CONTACT_STATUSES,
  CUSTOM_REQUEST_STATUSES,
  DIGITAL_FORMATS,
  DISCOUNT_TYPES,
  OPTION_TYPES,
  ORDER_STATUSES,
  PAYMENT_METHODS,
  PAYMENT_STATUSES,
  PRODUCT_STATUSES,
  PRODUCT_TYPES,
} from "@/lib/domain";

// Conventions
// - IDs are random UUID strings generated by the application.
// - Timestamps are integer milliseconds since epoch (Drizzle maps them to Date).
// - Money is an integer number of whole Iraqi dinars (IQD has no fractional
//   unit in practice). Never store money as REAL.
// - Bilingual content is stored as explicit *_en / *_ar columns.

const id = () =>
  text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID());
const createdAt = () =>
  integer("created_at", { mode: "timestamp_ms" })
    .notNull()
    .$defaultFn(() => new Date());
const updatedAt = () =>
  integer("updated_at", { mode: "timestamp_ms" })
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdateFn(() => new Date());
const bool = (name: string) => integer(name, { mode: "boolean" });

// ---------------------------------------------------------------------------
// Customers
// ---------------------------------------------------------------------------

export const users = sqliteTable(
  "users",
  {
    id: id(),
    /** E.164, e.g. +9647701234567. */
    phone: text("phone").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    status: text("status", { enum: ACCOUNT_STATUSES }).notNull().default("ACTIVE"),
    locale: text("locale").notNull().default("ar"),
    lastLoginAt: integer("last_login_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_phone_uq").on(t.phone)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    /** SHA-256 of the cookie token. The raw token is never stored. */
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    lastSeenAt: integer("last_seen_at", { mode: "timestamp_ms" }).notNull(),
    ipHash: text("ip_hash"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_user_idx").on(t.userId), index("sessions_expires_idx").on(t.expiresAt)],
);

export const passwordResetTokens = sqliteTable(
  "password_reset_tokens",
  {
    /** SHA-256 of the token in the reset link. */
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdByAdminId: text("created_by_admin_id").references(() => adminUsers.id, {
      onDelete: "set null",
    }),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    usedAt: integer("used_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
  },
  (t) => [index("prt_user_idx").on(t.userId)],
);

export const addresses = sqliteTable(
  "addresses",
  {
    id: id(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    fullName: text("full_name").notNull(),
    phone: text("phone").notNull(),
    zoneId: text("zone_id").references(() => deliveryZones.id, { onDelete: "set null" }),
    areaId: text("area_id").references(() => deliveryAreas.id, { onDelete: "set null" }),
    city: text("city").notNull(),
    district: text("district").notNull(),
    addressLine: text("address_line").notNull(),
    landmark: text("landmark"),
    isDefault: bool("is_default").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("addresses_user_idx").on(t.userId)],
);

// ---------------------------------------------------------------------------
// Administrators (separate identity store from customers)
// ---------------------------------------------------------------------------

export const adminUsers = sqliteTable(
  "admin_users",
  {
    id: id(),
    /** Lower-case login name. */
    username: text("username").notNull(),
    displayName: text("display_name").notNull(),
    role: text("role", { enum: ADMIN_ROLES }).notNull(),
    passwordHash: text("password_hash").notNull(),
    /** AES-GCM encrypted base32 TOTP secret (see server/auth/totp.ts). */
    totpSecretEnc: text("totp_secret_enc"),
    totpEnabled: bool("totp_enabled").notNull().default(false),
    /** Last accepted TOTP time-step, to reject code replay. */
    totpLastCounter: integer("totp_last_counter"),
    status: text("status", { enum: ACCOUNT_STATUSES }).notNull().default("ACTIVE"),
    failedLoginCount: integer("failed_login_count").notNull().default(0),
    lockedUntil: integer("locked_until", { mode: "timestamp_ms" }),
    lastLoginAt: integer("last_login_at", { mode: "timestamp_ms" }),
    passwordChangedAt: integer("password_changed_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("admin_users_username_uq").on(t.username)],
);

export const adminSessions = sqliteTable(
  "admin_sessions",
  {
    id: text("id").primaryKey(),
    adminId: text("admin_id")
      .notNull()
      .references(() => adminUsers.id, { onDelete: "cascade" }),
    /** MFA_PENDING sessions can only complete the TOTP step. */
    stage: text("stage", { enum: ["MFA_PENDING", "ACTIVE"] }).notNull(),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    lastSeenAt: integer("last_seen_at", { mode: "timestamp_ms" }).notNull(),
    mfaAttempts: integer("mfa_attempts").notNull().default(0),
    ipHash: text("ip_hash"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("admin_sessions_admin_idx").on(t.adminId)],
);

// ---------------------------------------------------------------------------
// Catalog
// ---------------------------------------------------------------------------

export const categories = sqliteTable(
  "categories",
  {
    id: id(),
    parentId: text("parent_id").references((): AnySQLiteColumn => categories.id, {
      onDelete: "restrict",
    }),
    slug: text("slug").notNull(),
    nameEn: text("name_en").notNull(),
    nameAr: text("name_ar").notNull(),
    descriptionEn: text("description_en").notNull().default(""),
    descriptionAr: text("description_ar").notNull().default(""),
    sortOrder: integer("sort_order").notNull().default(0),
    isActive: bool("is_active").notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("categories_slug_uq").on(t.slug), index("categories_parent_idx").on(t.parentId)],
);

export type LocalizedText = { en: string; ar: string };
export type Specification = { label: LocalizedText; value: LocalizedText };

export const products = sqliteTable(
  "products",
  {
    id: id(),
    slug: text("slug").notNull(),
    productType: text("product_type", { enum: PRODUCT_TYPES }).notNull(),
    categoryId: text("category_id")
      .notNull()
      .references(() => categories.id, { onDelete: "restrict" }),
    nameEn: text("name_en").notNull(),
    nameAr: text("name_ar").notNull(),
    summaryEn: text("summary_en").notNull().default(""),
    summaryAr: text("summary_ar").notNull().default(""),
    descriptionEn: text("description_en").notNull().default(""),
    descriptionAr: text("description_ar").notNull().default(""),
    basePrice: integer("base_price").notNull(),
    salePrice: integer("sale_price"),
    /** Unit production/purchase cost, admin-only, used for profit analytics. */
    costPrice: integer("cost_price"),
    currency: text("currency", { enum: ["IQD"] }).notNull().default("IQD"),
    availability: text("availability", { enum: AVAILABILITY }).notNull(),
    /** Only enforced when availability = IN_STOCK. */
    stockQuantity: integer("stock_quantity"),
    productionDaysMin: integer("production_days_min"),
    productionDaysMax: integer("production_days_max"),
    lengthMm: integer("length_mm"),
    widthMm: integer("width_mm"),
    heightMm: integer("height_mm"),
    weightGrams: integer("weight_grams"),
    materials: text("materials", { mode: "json" }).$type<string[]>().notNull().default([]),
    colors: text("colors", { mode: "json" }).$type<string[]>().notNull().default([]),
    tags: text("tags", { mode: "json" }).$type<string[]>().notNull().default([]),
    specifications: text("specifications", { mode: "json" })
      .$type<Specification[]>()
      .notNull()
      .default([]),
    features: text("features", { mode: "json" }).$type<LocalizedText[]>().notNull().default([]),
    included: text("included", { mode: "json" }).$type<LocalizedText[]>().notNull().default([]),
    seoTitleEn: text("seo_title_en"),
    seoTitleAr: text("seo_title_ar"),
    seoDescriptionEn: text("seo_description_en"),
    seoDescriptionAr: text("seo_description_ar"),
    /** R2 key (MEDIA bucket) of a GLB used for the in-browser 3D preview. */
    previewModelKey: text("preview_model_key"),
    status: text("status", { enum: PRODUCT_STATUSES }).notNull().default("DRAFT"),
    isFeatured: bool("is_featured").notNull().default(false),
    /** Normalized EN+AR text used for search (see lib/search-normalize.ts). */
    searchText: text("search_text").notNull().default(""),
    publishedAt: integer("published_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("products_slug_uq").on(t.slug),
    index("products_status_created_idx").on(t.status, t.createdAt),
    index("products_category_idx").on(t.categoryId),
    index("products_type_idx").on(t.productType),
    check("products_price_ck", sql`${t.basePrice} >= 0 AND (${t.salePrice} IS NULL OR ${t.salePrice} >= 0)`),
    check("products_cost_ck", sql`${t.costPrice} IS NULL OR ${t.costPrice} >= 0`),
    // Makes concurrent checkouts of the last in-stock unit fail atomically.
    check("products_stock_ck", sql`${t.stockQuantity} IS NULL OR ${t.stockQuantity} >= 0`),
  ],
);

export const productImages = sqliteTable(
  "product_images",
  {
    id: id(),
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    r2Key: text("r2_key").notNull(),
    width: integer("width"),
    height: integer("height"),
    altEn: text("alt_en").notNull().default(""),
    altAr: text("alt_ar").notNull().default(""),
    /** Lowest sort order is the primary image. */
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [index("product_images_product_idx").on(t.productId, t.sortOrder)],
);

export const productOptions = sqliteTable(
  "product_options",
  {
    id: id(),
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    type: text("type", { enum: OPTION_TYPES }).notNull(),
    labelEn: text("label_en").notNull(),
    labelAr: text("label_ar").notNull(),
    helpEn: text("help_en").notNull().default(""),
    helpAr: text("help_ar").notNull().default(""),
    isRequired: bool("is_required").notNull().default(false),
    /** Flat surcharge when TEXT/TEXTAREA/FILE is filled or a value-less CHECKBOX is ticked. */
    priceDelta: integer("price_delta").notNull().default(0),
    /** NUMBER only: surcharge per unit above minValue. */
    pricePerUnit: integer("price_per_unit").notNull().default(0),
    /** NUMBER: value range. TEXT/TEXTAREA: minValue/maxValue are length bounds. */
    minValue: integer("min_value"),
    maxValue: integer("max_value"),
    unitEn: text("unit_en").notNull().default(""),
    unitAr: text("unit_ar").notNull().default(""),
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index("product_options_product_idx").on(t.productId, t.sortOrder),
    check("product_options_price_ck", sql`${t.priceDelta} >= 0 AND ${t.pricePerUnit} >= 0`),
  ],
);

export const productOptionValues = sqliteTable(
  "product_option_values",
  {
    id: id(),
    optionId: text("option_id")
      .notNull()
      .references(() => productOptions.id, { onDelete: "cascade" }),
    labelEn: text("label_en").notNull(),
    labelAr: text("label_ar").notNull(),
    priceDelta: integer("price_delta").notNull().default(0),
    /** Optional swatch colour (#rrggbb) for colour choices. */
    swatch: text("swatch"),
    isDefault: bool("is_default").notNull().default(false),
    isActive: bool("is_active").notNull().default(true),
    sortOrder: integer("sort_order").notNull().default(0),
  },
  (t) => [
    index("product_option_values_option_idx").on(t.optionId, t.sortOrder),
    check("product_option_values_price_ck", sql`${t.priceDelta} >= 0`),
  ],
);

export const productRelations = sqliteTable(
  "product_relations",
  {
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    relatedProductId: text("related_product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    sortOrder: integer("sort_order").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.productId, t.relatedProductId] })],
);

export const digitalFiles = sqliteTable(
  "digital_files",
  {
    id: id(),
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "restrict" }),
    /** R2 key in the PRIVATE_FILES bucket. Never exposed to clients. */
    r2Key: text("r2_key").notNull(),
    filename: text("filename").notNull(),
    format: text("format", { enum: DIGITAL_FORMATS }).notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    isActive: bool("is_active").notNull().default(true),
    uploadedBy: text("uploaded_by").references(() => adminUsers.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("digital_files_product_idx").on(t.productId)],
);

// ---------------------------------------------------------------------------
// Delivery
// ---------------------------------------------------------------------------

export const deliveryZones = sqliteTable(
  "delivery_zones",
  {
    id: id(),
    /** Stable governorate code, e.g. "BGD". */
    code: text("code").notNull(),
    nameEn: text("name_en").notNull(),
    nameAr: text("name_ar").notNull(),
    fee: integer("fee").notNull(),
    etaDaysMin: integer("eta_days_min").notNull().default(1),
    etaDaysMax: integer("eta_days_max").notNull().default(3),
    isActive: bool("is_active").notNull().default(true),
    sortOrder: integer("sort_order").notNull().default(0),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("delivery_zones_code_uq").on(t.code), check("delivery_zones_fee_ck", sql`${t.fee} >= 0`)],
);

/** Optional per-area fee overrides inside a governorate. */
export const deliveryAreas = sqliteTable(
  "delivery_areas",
  {
    id: id(),
    zoneId: text("zone_id")
      .notNull()
      .references(() => deliveryZones.id, { onDelete: "cascade" }),
    nameEn: text("name_en").notNull(),
    nameAr: text("name_ar").notNull(),
    fee: integer("fee").notNull(),
    isActive: bool("is_active").notNull().default(true),
    sortOrder: integer("sort_order").notNull().default(0),
  },
  (t) => [
    uniqueIndex("delivery_areas_zone_name_uq").on(t.zoneId, t.nameEn),
    check("delivery_areas_fee_ck", sql`${t.fee} >= 0`),
  ],
);

// ---------------------------------------------------------------------------
// Discounts
// ---------------------------------------------------------------------------

export const discounts = sqliteTable(
  "discounts",
  {
    id: id(),
    /** Upper-case code customers type at checkout. */
    code: text("code").notNull(),
    description: text("description").notNull().default(""),
    type: text("type", { enum: DISCOUNT_TYPES }).notNull(),
    /** PERCENT: 1-100. FIXED: whole IQD. */
    value: integer("value").notNull(),
    minSubtotal: integer("min_subtotal").notNull().default(0),
    /** PERCENT only: optional cap in IQD. */
    maxDiscount: integer("max_discount"),
    maxUses: integer("max_uses"),
    usedCount: integer("used_count").notNull().default(0),
    startsAt: integer("starts_at", { mode: "timestamp_ms" }),
    endsAt: integer("ends_at", { mode: "timestamp_ms" }),
    isActive: bool("is_active").notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("discounts_code_uq").on(t.code),
    check("discounts_value_ck", sql`${t.value} > 0 AND (${t.type} <> 'PERCENT' OR ${t.value} <= 100)`),
    // Concurrent redemptions past the limit fail atomically inside the order batch.
    check("discounts_uses_ck", sql`${t.maxUses} IS NULL OR ${t.usedCount} <= ${t.maxUses}`),
  ],
);

// ---------------------------------------------------------------------------
// Visitor-owned uploads (customer files for custom prints / FILE options)
// ---------------------------------------------------------------------------

export const uploads = sqliteTable(
  "uploads",
  {
    id: id(),
    /** "user:<id>" or "visitor:<sha256>"; only the owner may attach it. */
    ownerKey: text("owner_key").notNull(),
    purpose: text("purpose", { enum: ["CUSTOM_PRINT", "PRODUCT_OPTION"] }).notNull(),
    r2Key: text("r2_key").notNull(),
    filename: text("filename").notNull(),
    extension: text("extension").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    /** Set once attached to an order or custom request; then immutable. */
    attachedType: text("attached_type", { enum: ["ORDER", "CUSTOM_REQUEST"] }),
    attachedId: text("attached_id"),
    createdAt: createdAt(),
  },
  (t) => [index("uploads_owner_idx").on(t.ownerKey), index("uploads_attached_idx").on(t.attachedType, t.attachedId)],
);

// ---------------------------------------------------------------------------
// Carts
// ---------------------------------------------------------------------------

export const carts = sqliteTable(
  "carts",
  {
    id: id(),
    userId: text("user_id").references(() => users.id, { onDelete: "cascade" }),
    /** SHA-256 of the anonymous visitor cookie token. */
    visitorHash: text("visitor_hash"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("carts_user_uq").on(t.userId), uniqueIndex("carts_visitor_uq").on(t.visitorHash)],
);

export type SelectedOptions = Record<string, string | string[] | number | boolean>;

export const cartItems = sqliteTable(
  "cart_items",
  {
    id: id(),
    cartId: text("cart_id")
      .notNull()
      .references(() => carts.id, { onDelete: "cascade" }),
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    quantity: integer("quantity").notNull(),
    /** Raw option selections keyed by option id; re-validated on every read. */
    options: text("options", { mode: "json" }).$type<SelectedOptions>().notNull().default({}),
    /** Deterministic hash of product + options so identical lines merge. */
    lineKey: text("line_key").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("cart_items_line_uq").on(t.cartId, t.lineKey),
    check("cart_items_qty_ck", sql`${t.quantity} > 0 AND ${t.quantity} <= 100`),
  ],
);

// ---------------------------------------------------------------------------
// Orders
// ---------------------------------------------------------------------------

export const orders = sqliteTable(
  "orders",
  {
    id: id(),
    orderNumber: text("order_number").notNull(),
    userId: text("user_id").references(() => users.id, { onDelete: "set null" }),
    /** SHA-256 of (owner + client idempotency key); blocks duplicate submits. */
    idempotencyKey: text("idempotency_key").notNull(),
    /** SHA-256 of the secret token in the order-tracking link. */
    accessTokenHash: text("access_token_hash").notNull(),
    customerName: text("customer_name").notNull(),
    customerPhone: text("customer_phone").notNull(),
    status: text("status", { enum: ORDER_STATUSES }).notNull().default("PENDING"),
    paymentMethod: text("payment_method", { enum: PAYMENT_METHODS }).notNull().default("COD"),
    paymentStatus: text("payment_status", { enum: PAYMENT_STATUSES }).notNull().default("PENDING"),
    currency: text("currency", { enum: ["IQD"] }).notNull().default("IQD"),
    subtotal: integer("subtotal").notNull(),
    discountTotal: integer("discount_total").notNull().default(0),
    deliveryFee: integer("delivery_fee").notNull().default(0),
    total: integer("total").notNull(),
    discountId: text("discount_id").references(() => discounts.id, { onDelete: "set null" }),
    discountCode: text("discount_code"),
    hasPhysical: bool("has_physical").notNull(),
    hasDigital: bool("has_digital").notNull(),
    // Delivery address snapshot (null for digital-only orders).
    deliveryZoneId: text("delivery_zone_id").references(() => deliveryZones.id, { onDelete: "set null" }),
    governorateEn: text("governorate_en"),
    governorateAr: text("governorate_ar"),
    city: text("city"),
    district: text("district"),
    addressLine: text("address_line"),
    landmark: text("landmark"),
    deliveryNotes: text("delivery_notes"),
    orderNotes: text("order_notes"),
    adminNotes: text("admin_notes"),
    locale: text("locale").notNull().default("ar"),
    customRequestId: text("custom_request_id"),
    confirmedAt: integer("confirmed_at", { mode: "timestamp_ms" }),
    deliveredAt: integer("delivered_at", { mode: "timestamp_ms" }),
    cancelledAt: integer("cancelled_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("orders_number_uq").on(t.orderNumber),
    uniqueIndex("orders_idempotency_uq").on(t.idempotencyKey),
    index("orders_user_idx").on(t.userId, t.createdAt),
    index("orders_status_idx").on(t.status, t.createdAt),
    index("orders_created_idx").on(t.createdAt),
    index("orders_phone_idx").on(t.customerPhone),
    check(
      "orders_money_ck",
      sql`${t.subtotal} >= 0 AND ${t.discountTotal} >= 0 AND ${t.deliveryFee} >= 0 AND ${t.discountTotal} <= ${t.subtotal} AND ${t.total} = ${t.subtotal} - ${t.discountTotal} + ${t.deliveryFee}`,
    ),
  ],
);

export type OptionSnapshot = {
  optionId: string;
  label: LocalizedText;
  /** Human-readable selected value(s). */
  value: LocalizedText;
  priceDelta: number;
  uploadId?: string;
};

export const orderItems = sqliteTable(
  "order_items",
  {
    id: id(),
    orderId: text("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: text("product_id").references(() => products.id, { onDelete: "set null" }),
    // Snapshot of the product at purchase time.
    productSlug: text("product_slug").notNull(),
    productNameEn: text("product_name_en").notNull(),
    productNameAr: text("product_name_ar").notNull(),
    productType: text("product_type", { enum: PRODUCT_TYPES }).notNull(),
    imageKey: text("image_key"),
    unitPrice: integer("unit_price").notNull(),
    unitCost: integer("unit_cost"),
    quantity: integer("quantity").notNull(),
    lineTotal: integer("line_total").notNull(),
    options: text("options", { mode: "json" }).$type<OptionSnapshot[]>().notNull().default([]),
    isPhysical: bool("is_physical").notNull(),
    isDigital: bool("is_digital").notNull(),
    /** True when checkout decremented products.stock_quantity (restored on cancel). */
    stockDeducted: bool("stock_deducted").notNull().default(false),
    downloadCount: integer("download_count").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index("order_items_order_idx").on(t.orderId),
    index("order_items_product_idx").on(t.productId),
    check(
      "order_items_money_ck",
      sql`${t.quantity} > 0 AND ${t.unitPrice} >= 0 AND ${t.lineTotal} = ${t.unitPrice} * ${t.quantity}`,
    ),
  ],
);

export const orderStatusHistory = sqliteTable(
  "order_status_history",
  {
    id: id(),
    orderId: text("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    fromStatus: text("from_status", { enum: ORDER_STATUSES }),
    toStatus: text("to_status", { enum: ORDER_STATUSES }).notNull(),
    actorType: text("actor_type", { enum: ["CUSTOMER", "ADMIN", "SYSTEM"] }).notNull(),
    actorId: text("actor_id"),
    actorLabel: text("actor_label").notNull(),
    /** Shown to the customer when set. */
    publicNote: text("public_note"),
    createdAt: createdAt(),
  },
  (t) => [index("order_status_history_order_idx").on(t.orderId, t.createdAt)],
);

// ---------------------------------------------------------------------------
// Custom print requests
// ---------------------------------------------------------------------------

export const customPrintRequests = sqliteTable(
  "custom_print_requests",
  {
    id: id(),
    requestNumber: text("request_number").notNull(),
    userId: text("user_id").references(() => users.id, { onDelete: "set null" }),
    accessTokenHash: text("access_token_hash").notNull(),
    customerName: text("customer_name").notNull(),
    customerPhone: text("customer_phone").notNull(),
    material: text("material").notNull(),
    color: text("color").notNull(),
    scalePercent: integer("scale_percent").notNull().default(100),
    quantity: integer("quantity").notNull(),
    notes: text("notes").notNull().default(""),
    status: text("status", { enum: CUSTOM_REQUEST_STATUSES }).notNull().default("SUBMITTED"),
    quotedPrice: integer("quoted_price"),
    productionDays: integer("production_days"),
    /** Visible to the customer (quote explanation, rejection reason). */
    customerMessage: text("customer_message"),
    /** Internal only. */
    adminNotes: text("admin_notes"),
    orderId: text("order_id").references(() => orders.id, { onDelete: "set null" }),
    locale: text("locale").notNull().default("ar"),
    reviewedBy: text("reviewed_by").references(() => adminUsers.id, { onDelete: "set null" }),
    reviewedAt: integer("reviewed_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("custom_requests_number_uq").on(t.requestNumber),
    index("custom_requests_status_idx").on(t.status, t.createdAt),
    index("custom_requests_user_idx").on(t.userId),
    check("custom_requests_qty_ck", sql`${t.quantity} > 0 AND ${t.quantity} <= 1000`),
    check("custom_requests_price_ck", sql`${t.quotedPrice} IS NULL OR ${t.quotedPrice} > 0`),
  ],
);

// ---------------------------------------------------------------------------
// Customer engagement
// ---------------------------------------------------------------------------

export const wishlistItems = sqliteTable(
  "wishlist_items",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    productId: text("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.productId] })],
);

export const contactMessages = sqliteTable(
  "contact_messages",
  {
    id: id(),
    name: text("name").notNull(),
    phone: text("phone").notNull(),
    subject: text("subject").notNull(),
    message: text("message").notNull(),
    status: text("status", { enum: CONTACT_STATUSES }).notNull().default("NEW"),
    locale: text("locale").notNull().default("ar"),
    createdAt: createdAt(),
  },
  (t) => [index("contact_messages_status_idx").on(t.status, t.createdAt)],
);

// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

export const siteSettings = sqliteTable("site_settings", {
  key: text("key").primaryKey(),
  value: text("value", { mode: "json" }).notNull(),
  updatedBy: text("updated_by").references(() => adminUsers.id, { onDelete: "set null" }),
  updatedAt: updatedAt(),
});

export const auditLogs = sqliteTable(
  "audit_logs",
  {
    id: id(),
    actorAdminId: text("actor_admin_id").references(() => adminUsers.id, { onDelete: "set null" }),
    actorLabel: text("actor_label").notNull(),
    action: text("action").notNull(),
    targetType: text("target_type"),
    targetId: text("target_id"),
    metadata: text("metadata", { mode: "json" }).$type<Record<string, unknown>>(),
    ipHash: text("ip_hash"),
    createdAt: createdAt(),
  },
  (t) => [
    index("audit_logs_created_idx").on(t.createdAt),
    index("audit_logs_actor_idx").on(t.actorAdminId, t.createdAt),
    index("audit_logs_target_idx").on(t.targetType, t.targetId),
  ],
);

export const rateLimits = sqliteTable("rate_limits", {
  /** "<bucket>:<identifier>:<window start>" */
  key: text("key").primaryKey(),
  count: integer("count").notNull(),
  expiresAt: integer("expires_at").notNull(),
});
